function envelope(value, depth = 0) {
  if (value == null || depth > 8) return null;
  if (typeof value === 'string') {
    try { return envelope(JSON.parse(value), depth + 1); } catch { return null; }
  }
  if (Array.isArray(value)) {
    for (const entry of value) { const result = envelope(entry, depth + 1); if (result) return result; }
    return null;
  }
  if (typeof value === 'object') {
    if (typeof value.ok === 'boolean' && 'data' in value) return value;
    for (const key of ['json', 'response', 'body', 'output', 'data']) {
      const result = envelope(value[key], depth + 1); if (result) return result;
    }
  }
