  const result = envelope(pipelineSteps[pipelineSteps.length - 1].observation ?? pipelineSteps[pipelineSteps.length - 1].output);
  const data = result?.data;
  const valid = result?.ok === true && Array.isArray(data?.stages) && data.stages.length > 0 &&
    data.stages.every(s => typeof s.stage === 'string' && Number.isInteger(s.count) && s.count >= 0) &&
    data.metrics && typeof data.metrics === 'object' && Number.isFinite(data.metrics.total_leads);
  if (valid) {
    const stages = data.stages.map(s => `${s.stage}: ${s.count}`).join(', ');
    const keys = ['total_leads', 'new_7d', 'stalled_count', 'high_intent_count', 'needs_review_count',
      'viewings_upcoming', 'completion_rate', 'viewing_rate'];
    const metrics = keys.filter(k => Number.isFinite(data.metrics[k])).map(k => `${k}: ${data.metrics[k]}`).join(', ');
    reply = `Pipeline by stage - ${stages}. Aggregate metrics - ${metrics}.`;
